import hashlib
import hmac
import time
import os
import struct
import threading
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['TOKEN_EXPIRY'] = 3600

# In-memory user store
USERS = {
    'admin': {'password_hash': hashlib.sha256(b'admin_pass_2024!').hexdigest(), 'role': 'admin'},
    'user1': {'password_hash': hashlib.sha256(b'user1_pass_2024!').hexdigest(), 'role': 'user'},
}

# Rate limiter state
rate_limit_store = {}
rate_limit_lock = threading.Lock()

MAX_REQUESTS = 100
WINDOW_SIZE = 60  # seconds


def generate_token(username, role):
    """Generate HMAC-based authentication token with expiry."""
    timestamp = int(time.time())
    # Pack: username_len (1 byte) + username + role_len (1 byte) + role + timestamp (4 bytes)
    payload = struct.pack('B', len(username)) + username.encode('utf-8')
    payload += struct.pack('B', len(role)) + role.encode('utf-8')
    payload += struct.pack('>I', timestamp)

    signature = hmac.new(app.config['SECRET_KEY'], payload, hashlib.sha256).digest()
    token = payload + signature
    return token.hex()


def verify_token(token_hex):
    """Verify token integrity and extract claims."""
    try:
        token = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token) < 35:  # minimum: 1+1+1+1+4+32 = 40, but be lenient
        return None

    # Parse payload
    offset = 0
    username_len = token[offset]
    offset += 1

    if offset + username_len > len(token) - 32:
        return None
    username = token[offset:offset + username_len].decode('utf-8', errors='replace')
    offset += username_len

    role_len = token[offset]
    offset += 1

    if offset + role_len > len(token) - 32:
        return None
    role = token[offset:offset + role_len].decode('utf-8', errors='replace')
    offset += role_len

    # Extract timestamp (4 bytes, big-endian unsigned)
    if offset + 4 > len(token) - 32:
        return None
    timestamp = struct.unpack('>I', token[offset:offset + 4])[0]
    offset += 4

    # Verify expiry
    current_time = int(time.time())
    elapsed = current_time - timestamp

    # Check if token has expired
    # elapsed is a signed integer; if timestamp is in the future, elapsed is negative
    if elapsed > app.config['TOKEN_EXPIRY']:
        return None

    # Verify HMAC
    payload = token[:offset]
    provided_sig = token[offset:offset + 32]

    expected_sig = hmac.new(app.config['SECRET_KEY'], payload, hashlib.sha256).digest()

    if not hmac.compare_digest(provided_sig, expected_sig):
        return None

    return {'username': username, 'role': role, 'timestamp': timestamp}


def check_rate_limit(client_id):
    """Token bucket rate limiter."""
    current_time = int(time.time())

    with rate_limit_lock:
        if client_id not in rate_limit_store:
            rate_limit_store[client_id] = {'tokens': MAX_REQUESTS - 1, 'last_refill': current_time}
            return True

        bucket = rate_limit_store[client_id]
        time_passed = current_time - bucket['last_refill']

        # Refill tokens based on time passed
        refill_amount = int(time_passed * (MAX_REQUESTS / WINDOW_SIZE))
        bucket['tokens'] = min(MAX_REQUESTS, bucket['tokens'] + refill_amount)
        bucket['last_refill'] = current_time

        if bucket['tokens'] > 0:
            bucket['tokens'] -= 1
            return True
        return False


def require_auth(required_role=None):
    """Decorator for authenticated endpoints."""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            # Rate limiting by IP
            client_ip = request.remote_addr or '127.0.0.1'
            if not check_rate_limit(client_ip):
                return jsonify({'error': 'Rate limit exceeded'}), 429

            # Extract token
            auth_header = request.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                return jsonify({'error': 'Missing authorization'}), 401

            token_hex = auth_header[7:]
            claims = verify_token(token_hex)

            if claims is None:
                return jsonify({'error': 'Invalid or expired token'}), 401

            # Role check
            if required_role and claims['role'] != required_role:
                return jsonify({'error': 'Insufficient privileges'}), 403

            g.current_user = claims
            return f(*args, **kwargs)
        return decorated_function
    return decorator


@app.route('/auth/login', methods=['POST'])
def login():
    """Authenticate user and return token."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    # Rate limit login attempts
    client_ip = request.remote_addr or '127.0.0.1'
    if not check_rate_limit(f'login_{client_ip}'):
        return jsonify({'error': 'Too many login attempts'}), 429

    user = USERS.get(username)
    if not user:
        # Constant-time comparison even for non-existent users
        hmac.compare_digest(hashlib.sha256(password.encode()).hexdigest(), 'x' * 64)
        return jsonify({'error': 'Invalid credentials'}), 401

    password_hash = hashlib.sha256(password.encode()).hexdigest()
    if not hmac.compare_digest(password_hash, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_token(username, user['role'])
    return jsonify({'token': token, 'expires_in': app.config['TOKEN_EXPIRY']})


